/**
 * PATİKA — YOLCULUK MOTORU (bayraklı deneme, 14 Ağu 2026)
 *
 * Gerçek perspektif izdüşümü: kamera Z ekseninde ilerler, her nesne kendi
 * uzaklığına bölünerek ölçeklenir (olcek = ODAK*W/uzaklik). Katman kaydırma YOK —
 * tabela uzakta doğar, yaklaşırken büyür, aracın yanından geçip arkada kalır.
 *
 * WebView içinde çalışır (kitap.tsx'teki PDF görüntüleyici düzeninin aynısı).
 * RN → motor:  window.patikaKur(JSON)  { kanun, duraklar:[{id,no,ad,tamam}], aktif }
 * motor → RN:  {tip:'hazir'} · {tip:'durak', id}
 *
 * ELLE DÜZENLEME: kaynağı scratchpad/yolculuk-app.html — görseller data-URI olarak
 * gömülüdür (zirve arka planı + arkadan jandarma aracı).
 */
export const PATIKA_YOLCULUK_HTML = `<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover">
<style>
  :root{ --krem:#F7F3EA; --altin:#C9A227; --altinAcik:#F0B733; --panel:rgba(4,26,36,.72); --kenar:rgba(240,183,51,.28); }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{margin:0;background:#04222e;color:#F7F3EA;overflow:hidden;
       font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;
       -webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}
  canvas{display:block;width:100%;height:100%}

  #ust{position:fixed;left:0;right:0;top:0;padding:10px 14px 18px;pointer-events:none;
       background:linear-gradient(180deg,rgba(2,16,24,.8),rgba(2,16,24,0));
       display:flex;flex-direction:column;gap:7px}
  #satir{display:flex;align-items:baseline;justify-content:space-between;gap:10px}
  #etap{font-size:12px;letter-spacing:3px;font-weight:700;color:var(--altinAcik);
        text-shadow:0 2px 8px rgba(0,0,0,.75)}
  #sayac{font-size:12px;font-weight:700;opacity:.92;font-variant-numeric:tabular-nums;
         text-shadow:0 2px 8px rgba(0,0,0,.75)}
  #cubuk{height:4px;border-radius:99px;background:rgba(255,255,255,.16);overflow:hidden}
  #dolu{height:100%;width:0;background:linear-gradient(90deg,var(--altin),var(--altinAcik));border-radius:99px}

  #ipucu{position:fixed;left:0;right:0;top:78px;text-align:center;font-size:11px;letter-spacing:2px;
         opacity:.65;pointer-events:none;transition:opacity .6s ease}
  #ipucu.gizle{opacity:0}

  /* Alt aksiyon: bulunduğun maddeyi aç */
  #ac{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(10px + env(safe-area-inset-bottom));
      padding:12px 22px;border:1px solid rgba(240,183,51,.6);border-radius:12px;
      background:linear-gradient(180deg,rgba(29,95,120,.95),rgba(9,45,60,.95));
      color:var(--krem);font-size:14px;font-weight:800;letter-spacing:.4px;
      -webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);
      box-shadow:0 8px 24px rgba(0,0,0,.45);cursor:pointer;white-space:nowrap}
  #ac:active{transform:translateX(-50%) translateY(1px)}

  #final{position:fixed;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;
         gap:8px;opacity:0;pointer-events:none;transition:opacity .9s ease;text-align:center;padding:20px}
  #final.gor{opacity:1}
  #fb{font-size:clamp(20px,6.5vw,40px);font-weight:800;letter-spacing:3px;color:var(--altinAcik);
      text-shadow:0 4px 24px rgba(0,0,0,.85)}
  #fa{font-size:12px;letter-spacing:6px;opacity:.85}
</style>

<canvas id="tuval"></canvas>

<div id="ust">
  <div id="satir"><div id="etap">VADİ</div><div id="sayac">—</div></div>
  <div id="cubuk"><div id="dolu"></div></div>
</div>
<div id="ipucu">↑ İLERLEMEK İÇİN PARMAĞINLA SÜRÜKLE</div>
<div id="final"><div id="fb">TAMAMLANDI</div><div id="fa">ZİRVE</div></div>
<button id="ac">MADDEYİ ÇALIŞ</button>

<script>
(() => {
'use strict';
const tuval=document.getElementById('tuval'), cx=tuval.getContext('2d');

/* ══ Perspektif tek formülden: olcek = ODAK*W/uzaklik.
      Kamera Z ekseninde gerçekten ilerler; her nesne uzaklığına bölünür. ══ */
const YOL_YARI=4.4, KAMERA_Y=2.55, ODAK=0.92, YAKIN=1.6, GORUS=300;
const ARALIK=38, DURAK_GERI=17, SERIT=1.2, ALT_BAR=64;

const ETAPLAR=[
  {ad:'VADİ',    t:0.06,sis:'#0e5266',zemin:['#17564f','#0a2b30'],agac:'#0c3f36',tur:'yaprak',siklik:1.0,hava:'rgba(10,90,110,.10)'},
  {ad:'ORMAN',   t:0.36,sis:'#083644',zemin:['#0e3a2c','#06231f'],agac:'#05241f',tur:'cam',   siklik:2.1,hava:'rgba(4,48,58,.20)'},
  {ad:'YÜKSELİŞ',t:0.64,sis:'#123c56',zemin:['#2b3440','#141c26'],agac:'#242e3a',tur:'kaya',  siklik:1.2,hava:'rgba(18,62,92,.14)'},
  {ad:'ZİRVE',   t:0.94,sis:'#33587a',zemin:['#7f95a8','#2b3a4a'],agac:'#16232f',tur:'kar',   siklik:0.9,hava:'rgba(70,110,150,.16)'},
];

const gorselUfuk=new Image(); gorselUfuk.src='data:image/webp;base64,';
const gorselArac=new Image(); gorselArac.src='data:image/webp;base64,';

let W=0,H=0,ufuk=0,dpr=1;
let duraklar=[];                 // [{id, no, ad, tamam}]
let adet=0, toplamYol=0, dagZ=0;
let durak=0, camZ=0, hedefZ=0, hiz=0;
let camY=KAMERA_Y, egim=0, finalMod=0, finalOynadi=false;
let nesneler=[], kanunAd='';
let tabelaKutu=[];               // dokunma isabeti için ekran dikdörtgenleri

function haber(o){ try{ window.ReactNativeWebView.postMessage(JSON.stringify(o)); }catch(_){} }
function tohum(s){ return () => (s=(s*1664525+1013904223)>>>0, s/4294967296); }

/* ══ RN'den gelen gerçek veri ══ */
window.patikaKur = function(json){
  let v; try{ v=typeof json==='string'?JSON.parse(json):json; }catch(_){ return; }
  duraklar = Array.isArray(v.duraklar)? v.duraklar : [];
  kanunAd = v.kanun || '';
  adet = duraklar.length;
  if(adet===0) return;
  const a = Number.isInteger(v.aktif) ? v.aktif : 0;
  durak = a>=0 && a<adet ? a : adet-1;
  dunyaKur();
  // Kanun bitmişse (aktif yok) zirve sineması bir kez oynasın.
  if(a<0 && !finalOynadi){ finalOynadi=true; setTimeout(finalBaslat, 700); }
};

function dunyaKur(){
  toplamYol=Math.max(1,adet-1)*ARALIK;
  dagZ=toplamYol*1.35+460;
  const rnd=tohum(20260814);
  nesneler=[];
  for(let z=8; z<toplamYol+GORUS; ){
    const e=etapKarisim(z/Math.max(1,toplamYol));
    z += (3.2+rnd()*4.6)/Math.max(.35,e.siklik);
    const kac = rnd()<0.42?2:1;
    for(let k=0;k<kac;k++){
      const sag = kac===2 ? k===0 : rnd()<0.5;
      nesneler.push({tip:'bitki',z,x:(sag?1:-1)*(YOL_YARI+1.9+rnd()*9),boy:2.0+rnd()*3.6,en:.55+rnd()*.7,r:rnd()});
    }
  }
  for(let z=6; z<toplamYol+GORUS; z+=11){
    nesneler.push({tip:'dikme',z,x:-(YOL_YARI+0.55),boy:1.05});
    nesneler.push({tip:'dikme',z,x:+(YOL_YARI+0.55),boy:1.05});
  }
  for(let i=0;i<adet;i++)
    nesneler.push({tip:'tabela',z:i*ARALIK,x:(i%2?-1:1)*(YOL_YARI+1.45),i});
  nesneler.sort((a,b)=>a.z-b.z);
  hedefZ=durak*ARALIK-DURAK_GERI; camZ=hedefZ; hiz=0;
  yaz();
}

function karistir(a,b,f){
  const p=h=>[parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)];
  const A=p(a),B=p(b);
  const m=(i)=>Math.round(A[i]+(B[i]-A[i])*f);
  return 'rgb('+m(0)+','+m(1)+','+m(2)+')';
}
function etapKarisim(t){
  let i=0; while(i<ETAPLAR.length-1 && t>ETAPLAR[i+1].t) i++;
  const a=ETAPLAR[i], b=ETAPLAR[Math.min(i+1,ETAPLAR.length-1)];
  const f=b===a?0:Math.max(0,Math.min(1,(t-a.t)/(b.t-a.t))), y=f*f*(3-2*f);
  return { ad:y<0.5?a.ad:b.ad, sis:karistir(a.sis,b.sis,y),
    zemin0:karistir(a.zemin[0],b.zemin[0],y), zemin1:karistir(a.zemin[1],b.zemin[1],y),
    agac:karistir(a.agac,b.agac,y), tur:y<0.5?a.tur:b.tur, turB:y<0.5?b.tur:a.tur,
    gecis:y<0.5?y*2:(1-y)*2, siklik:a.siklik+(b.siklik-a.siklik)*y, hava:y<0.5?a.hava:b.hava };
}

const ol=z=>ODAK*W/z, eX=(x,s)=>W/2+x*s, eY=(y,s)=>ufuk+(camY-y)*s;

function ciz(){
  if(adet===0){ cx.clearRect(0,0,W,H); return; }
  const ilerleme=Math.max(0,Math.min(1,(camZ+DURAK_GERI)/Math.max(1,toplamYol)));
  const e=etapKarisim(ilerleme);
  ufuk=H*(0.455+egim);
  tabelaKutu=[];

  const gok=cx.createLinearGradient(0,0,0,ufuk+H*0.06);
  gok.addColorStop(0,'#02141f'); gok.addColorStop(.55,'#053345'); gok.addColorStop(1,e.sis);
  cx.fillStyle=gok; cx.fillRect(0,0,W,ufuk+H*0.06);
  yildizlar();

  if(gorselUfuk.complete&&gorselUfuk.naturalWidth){
    const kalan=Math.max(60,dagZ-camZ), buyume=Math.min(2.6,dagZ/kalan);
    const gw=W*1.02*buyume, gh=gw*gorselUfuk.naturalHeight/gorselUfuk.naturalWidth;
    cx.save(); cx.globalAlpha=.92; cx.drawImage(gorselUfuk,W/2-gw/2,ufuk+2-gh,gw,gh); cx.restore();
    const etek=cx.createLinearGradient(0,ufuk-H*0.13,0,ufuk+3);
    etek.addColorStop(0,'rgba(0,0,0,0)'); etek.addColorStop(.65,e.sis); etek.addColorStop(1,e.sis);
    cx.fillStyle=etek; cx.fillRect(0,ufuk-H*0.13,W,H*0.13+3);
  }

  const zem=cx.createLinearGradient(0,ufuk,0,H);
  zem.addColorStop(0,e.zemin1); zem.addColorStop(.35,e.zemin0); zem.addColorStop(1,e.zemin1);
  cx.fillStyle=zem; cx.fillRect(0,ufuk-1,W,H-ufuk+1);

  const zl=[]; for(let k=0;k<=90;k++) zl.push(YAKIN*Math.pow(GORUS/YAKIN,1-k/90));
  cx.beginPath();
  zl.forEach((z,k)=>{ const s=ol(z); cx[k?'lineTo':'moveTo'](eX(-YOL_YARI,s),eY(0,s)); });
  for(let k=zl.length-1;k>=0;k--){ const s=ol(zl[k]); cx.lineTo(eX(YOL_YARI,s),eY(0,s)); }
  cx.closePath();
  const asf=cx.createLinearGradient(0,ufuk,0,H);
  asf.addColorStop(0,e.sis); asf.addColorStop(.18,'#182029'); asf.addColorStop(1,'#252d37');
  cx.fillStyle=asf; cx.fill();

  cx.save(); cx.clip();
  const ilk=Math.ceil((camZ+YAKIN)/(SERIT*6))*SERIT*6;
  for(let zw=ilk; zw<camZ+GORUS; zw+=SERIT*6){
    const dz=zw-camZ; if(dz<YAKIN) continue;
    const s=ol(dz);
    cx.fillStyle='rgba(255,255,255,'+(0.03*(1-dz/GORUS))+')';
    cx.fillRect(0,eY(0,s),W,Math.max(1,0.10*s));
  }
  cx.restore();

  serit(-YOL_YARI+0.42); serit(YOL_YARI-0.42); orta(); farlar();

  const pus=cx.createLinearGradient(0,ufuk-H*0.05,0,ufuk+H*0.16);
  pus.addColorStop(0,e.sis); pus.addColorStop(1,'rgba(0,0,0,0)');
  cx.globalAlpha=.85; cx.fillStyle=pus; cx.fillRect(0,ufuk-H*0.05,W,H*0.21); cx.globalAlpha=1;

  const gorunen=nesneler.filter(o=>o.z-camZ>YAKIN-0.5 && o.z-camZ<GORUS);
  for(let k=gorunen.length-1;k>=0;k--){
    const o=gorunen[k], dz=o.z-camZ, s=ol(dz);
    const solma=Math.max(0,Math.min(1,1.25-Math.pow(dz/GORUS,0.75)*1.25));
    if(solma<=0.02) continue;
    if(o.tip==='bitki'){ cx.globalAlpha=solma; bitki(o,s,e); }
    else if(o.tip==='dikme'){ cx.globalAlpha=solma; dikme(o,s); }
    else { cx.globalAlpha=solma*Math.max(0,Math.min(1,(150-dz)/35)); if(cx.globalAlpha>0.02) tabela(o,s); }
    cx.globalAlpha=1;
  }

  cx.fillStyle=e.hava; cx.fillRect(0,0,W,H);
  arac();

  document.getElementById('etap').textContent = e.ad;
  document.getElementById('dolu').style.width = (ilerleme*100).toFixed(1)+'%';
}

let yildizCache=null;
function yildizlar(){
  if(!yildizCache||yildizCache.w!==W){
    const rnd=tohum(77),p=[];
    for(let i=0;i<90;i++) p.push({x:rnd(),y:rnd()*0.5,r:rnd()*1.5+.3,a:rnd()*.6+.2});
    yildizCache={w:W,p};
  }
  cx.fillStyle='#dff1ff';
  for(const y of yildizCache.p){ cx.globalAlpha=y.a; cx.beginPath(); cx.arc(y.x*W,y.y*ufuk,y.r,0,6.28); cx.fill(); }
  cx.globalAlpha=1;
}
function serit(x){
  cx.beginPath();
  for(let k=0;k<=60;k++){ const z=YAKIN*Math.pow(GORUS/YAKIN,1-k/60),s=ol(z); cx[k?'lineTo':'moveTo'](eX(x-0.16,s),eY(0.01,s)); }
  for(let k=60;k>=0;k--){ const z=YAKIN*Math.pow(GORUS/YAKIN,1-k/60),s=ol(z); cx.lineTo(eX(x+0.16,s),eY(0.01,s)); }
  cx.closePath(); cx.fillStyle='rgba(232,238,246,.55)'; cx.fill();
}
function orta(){
  const P=7,U=3.4, ilk=Math.floor((camZ+YAKIN)/P)*P;
  for(let zw=ilk; zw<camZ+GORUS; zw+=P){
    let z0=zw-camZ, z1=z0+U;
    if(z1<YAKIN) continue; if(z0<YAKIN) z0=YAKIN;
    const s0=ol(z0), s1=ol(z1);
    cx.beginPath();
    cx.moveTo(eX(-0.17,s0),eY(0.02,s0)); cx.lineTo(eX(0.17,s0),eY(0.02,s0));
    cx.lineTo(eX(0.17,s1),eY(0.02,s1)); cx.lineTo(eX(-0.17,s1),eY(0.02,s1));
    cx.closePath(); cx.fillStyle='rgba(245,235,200,'+(0.75*(1-z0/GORUS))+')'; cx.fill();
  }
}
function farlar(){
  const s0=ol(YAKIN+1), s1=ol(54);
  const g=cx.createLinearGradient(0,eY(0,s0),0,eY(0,s1));
  g.addColorStop(0,'rgba(255,240,205,.20)'); g.addColorStop(1,'rgba(255,240,205,0)');
  cx.save(); cx.globalCompositeOperation='lighter'; cx.fillStyle=g;
  for(const yon of [-1,1]){
    cx.beginPath();
    cx.moveTo(eX(yon*0.5-1.5,s0),eY(0,s0)); cx.lineTo(eX(yon*0.5+1.5,s0),eY(0,s0));
    cx.lineTo(eX(yon*1.4+0.9,s1),eY(0,s1)); cx.lineTo(eX(yon*1.4-0.9,s1),eY(0,s1));
    cx.closePath(); cx.fill();
  }
  cx.restore();
}
function bitki(o,s,e){
  const x=eX(o.x,s), y=eY(0,s), h=o.boy*s, w=o.en*s;
  cx.fillStyle=e.agac;
  const tur = o.r<e.gecis*0.5 ? e.turB : e.tur;
  if(tur==='cam'||tur==='kar'){
    cx.beginPath(); cx.moveTo(x,y-h); cx.lineTo(x+w*0.85,y); cx.lineTo(x-w*0.85,y); cx.closePath(); cx.fill();
    cx.fillRect(x-w*0.1,y-h*0.1,w*0.2,h*0.12);
    if(tur==='kar'){ cx.fillStyle='rgba(226,240,252,.75)';
      cx.beginPath(); cx.moveTo(x,y-h); cx.lineTo(x+w*0.34,y-h*0.55); cx.lineTo(x-w*0.34,y-h*0.55); cx.closePath(); cx.fill(); }
  } else if(tur==='kaya'){
    cx.beginPath(); cx.moveTo(x-w,y); cx.lineTo(x-w*0.55,y-h*0.55); cx.lineTo(x+w*0.1,y-h*0.75);
    cx.lineTo(x+w*0.9,y-h*0.2); cx.lineTo(x+w,y); cx.closePath(); cx.fill();
  } else {
    cx.fillRect(x-w*0.09,y-h*0.55,w*0.18,h*0.55);
    cx.beginPath(); cx.ellipse(x,y-h*0.72,w*0.85,h*0.34,0,0,6.28); cx.fill();
  }
}
function dikme(o,s){
  const x=eX(o.x,s), y=eY(0,s), h=o.boy*s;
  cx.fillStyle='rgba(226,236,246,.6)'; cx.fillRect(x-Math.max(0.6,0.06*s),y-h,Math.max(1.2,0.12*s),h);
  cx.fillStyle='rgba(255,148,90,.95)'; cx.fillRect(x-Math.max(0.8,0.09*s),y-h,Math.max(1.6,0.18*s),Math.max(1.4,0.16*s));
}

/* ── MADDE TABELASI: gerçek numara + durum (tamam / aktif / ileri) ── */
function tabela(o,s){
  const d=duraklar[o.i]; if(!d) return;
  const EN=4.2, BOY=2.30, ALT=2.00;
  const x=eX(o.x,s), alt=eY(ALT,s), ust=eY(ALT+BOY,s), yer=eY(0,s);
  const w=EN*s, h=alt-ust;
  const aktif = o.i===durak, tamam = !!d.tamam;

  cx.fillStyle='#3c4653';
  cx.fillRect(x+(o.x<0?w*0.34:-w*0.34)-Math.max(0.8,0.05*s), ust+h*0.5, Math.max(1.6,0.1*s), yer-ust-h*0.5);

  cx.save();
  if(aktif){ cx.shadowColor='rgba(240,183,51,.9)'; cx.shadowBlur=Math.min(48,0.9*s); }
  const g=cx.createLinearGradient(0,ust,0,alt);
  if(tamam){ g.addColorStop(0,'#7a5f12'); g.addColorStop(1,'#3d2f07'); }
  else if(aktif){ g.addColorStop(0,'#123c52'); g.addColorStop(1,'#071e2b'); }
  else { g.addColorStop(0,'#0c2b3a'); g.addColorStop(1,'#061821'); }
  cx.fillStyle=g; cx.fillRect(x-w/2,ust,w,h);
  cx.restore();
  cx.lineWidth=Math.max(1,0.055*s);
  cx.strokeStyle = aktif?'rgba(240,183,51,.95)': tamam?'rgba(240,183,51,.75)':'rgba(240,183,51,.42)';
  cx.strokeRect(x-w/2,ust,w,h);

  const p=Math.max(6,h*0.30);
  cx.textAlign='center'; cx.textBaseline='middle';
  cx.fillStyle = aktif?'#F6E4A8':'rgba(247,243,234,.88)';
  cx.font='700 '+(p*0.62).toFixed(1)+'px -apple-system,Segoe UI,Arial';
  cx.fillText('MADDE', x, ust+h*0.26);
  const yazi=String(d.no||'').trim() || '•';
  const punto = yazi.length>3 ? p*0.95 : p*1.55;
  cx.font='800 '+punto.toFixed(1)+'px -apple-system,Segoe UI,Arial';
  cx.fillText(yazi, x, ust+h*0.64);
  if(tamam){                                   // tamamlanan maddeye tik
    cx.strokeStyle='#F0B733'; cx.lineWidth=Math.max(1.4,0.07*s); cx.lineCap='round';
    cx.beginPath();
    cx.moveTo(x+w*0.26, ust+h*0.20); cx.lineTo(x+w*0.34, ust+h*0.30); cx.lineTo(x+w*0.44, ust+h*0.10);
    cx.stroke();
  }
  if(h>14) tabelaKutu.push({i:o.i, x0:x-w/2, y0:ust, x1:x+w/2, y1:alt});
}

let zaman=0;
function arac(){
  if(!gorselArac.complete||!gorselArac.naturalWidth) return;
  const en=W*0.34, boy=en*gorselArac.naturalHeight/gorselArac.naturalWidth;
  const sal=Math.sin(zaman*7.5)*(0.9+Math.min(6,Math.abs(hiz)*0.14));
  const yat=Math.sin(zaman*2.1)*Math.min(4,Math.abs(hiz)*0.09);
  const x=W/2-en/2+yat, y=H-ALT_BAR-boy+sal;
  cx.save(); cx.globalAlpha=.45; cx.fillStyle='#000';
  cx.beginPath(); cx.ellipse(W/2,y+boy*0.97,en*0.44,boy*0.07,0,0,6.28); cx.fill(); cx.restore();
  cx.drawImage(gorselArac,x,y,en,boy);
  const nabiz=(Math.sin(zaman*9)+1)/2;
  cx.save(); cx.globalCompositeOperation='lighter';
  const lamba=(px,renk,a)=>{ const g=cx.createRadialGradient(px,y+boy*0.06,0,px,y+boy*0.06,en*0.10);
    g.addColorStop(0,renk); g.addColorStop(1,'rgba(0,0,0,0)'); cx.globalAlpha=a; cx.fillStyle=g;
    cx.fillRect(px-en*0.10,y+boy*0.06-en*0.10,en*0.20,en*0.20); };
  lamba(x+en*0.34,'rgba(255,60,60,.95)',0.35+0.65*nabiz);
  lamba(x+en*0.66,'rgba(70,140,255,.95)',0.35+0.65*(1-nabiz));
  cx.restore();
}

/* ══ HAREKET: sürükle + yay ══ */
let surukluyor=false, sonPY=0, sonPT=0, surukleHiz=0, basX=0, basY=0, basT=0, kaydi=false;
tuval.style.touchAction='none';
const ipucuGizle=()=>document.getElementById('ipucu').classList.add('gizle');

tuval.addEventListener('pointerdown',ev=>{
  if(adet===0) return;
  surukluyor=true; sonPY=ev.clientY; sonPT=performance.now(); surukleHiz=0; hiz=0;
  basX=ev.clientX; basY=ev.clientY; basT=sonPT; kaydi=false;
  try{ tuval.setPointerCapture(ev.pointerId); }catch(_){}
});
tuval.addEventListener('pointermove',ev=>{
  if(!surukluyor) return;
  const dy=ev.clientY-sonPY; sonPY=ev.clientY;
  const simdi=performance.now(), gecen=Math.max(8,simdi-sonPT); sonPT=simdi;
  if(Math.abs(ev.clientX-basX)>8 || Math.abs(ev.clientY-basY)>8){ kaydi=true; ipucuGizle(); }
  const birim=ARALIK/(H*0.42);
  const disari = camZ<-DURAK_GERI || camZ>toplamYol-DURAK_GERI;
  const adim=-dy*birim*(disari?0.28:1);
  camZ=Math.max(-DURAK_GERI-6,Math.min(toplamYol-DURAK_GERI+6,camZ+adim));
  surukleHiz=Math.max(-80,Math.min(80,adim/(gecen/1000)));
});
function birak(ev){
  if(!surukluyor) return;
  surukluyor=false;
  // DOKUNMA (sürükleme değil) → tabelaya isabet ettiyse o maddeyi aç
  if(!kaydi && performance.now()-basT<500){
    for(const k of tabelaKutu){
      if(basX>=k.x0-6 && basX<=k.x1+6 && basY>=k.y0-6 && basY<=k.y1+6){
        const d=duraklar[k.i];
        if(d){ durak=k.i; hedefZ=durak*ARALIK-DURAK_GERI; yaz(); haber({tip:'durak',id:d.id}); }
        return;
      }
    }
    return;
  }
  hiz=surukleHiz;
  const tahmin=camZ+hiz*0.30;
  durak=Math.max(0,Math.min(adet-1,Math.round((tahmin+DURAK_GERI)/ARALIK)));
  hedefZ=durak*ARALIK-DURAK_GERI; yaz();
}
tuval.addEventListener('pointerup',birak);
tuval.addEventListener('pointercancel',()=>{ surukluyor=false; });

let sonAn=0;
function dongu(an){
  const dt=Math.min(0.05,(an-sonAn)/1000||0.016); sonAn=an; zaman+=dt;
  if(surukluyor){ hiz=surukleHiz; surukleHiz*=Math.pow(0.02,dt); }
  else{
    const fark=hedefZ-camZ;
    hiz+=(fark*7.2-hiz*5.0)*dt;
    hiz=Math.max(-70,Math.min(70,hiz));
    camZ+=hiz*dt;
    if(Math.abs(fark)<0.02&&Math.abs(hiz)<0.05){ camZ=hedefZ; hiz=0; }
  }
  if(finalMod>0){
    finalMod=Math.min(1,finalMod+dt*0.38);
    const f=finalMod*finalMod*(3-2*finalMod);
    camY=KAMERA_Y+f*16; egim=f*0.14; camZ+=dt*26*(1-f*0.7);
    if(finalMod>0.55) document.getElementById('final').classList.add('gor');
  }
  ciz(); requestAnimationFrame(dongu);
}

function yaz(){
  const d=duraklar[durak];
  document.getElementById('sayac').textContent =
    (kanunAd? kanunAd+' · ':'') + (adet? (durak+1)+' / '+adet : '—');
  document.getElementById('ac').textContent =
    d ? ((d.no? 'MADDE '+d.no : (d.ad||'MADDE')) + (d.tamam?' · TEKRAR':'') ) : 'MADDEYİ ÇALIŞ';
}
function finalBaslat(){
  document.getElementById('fb').textContent=(kanunAd||'MEVZUAT')+' TAMAMLANDI';
  finalMod=0.001;
}
document.getElementById('ac').onclick=()=>{
  const d=duraklar[durak]; if(d) haber({tip:'durak',id:d.id});
};

function boyut(){
  dpr=Math.min(2,window.devicePixelRatio||1);
  W=window.innerWidth; H=window.innerHeight;
  tuval.width=Math.round(W*dpr); tuval.height=Math.round(H*dpr);
  cx.setTransform(dpr,0,0,dpr,0,0);
  yildizCache=null;
}
window.addEventListener('resize',boyut);
boyut(); requestAnimationFrame(dongu);
haber({tip:'hazir'});
})();
</script>
`;
